from datetime import datetime

access_token='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJzcG90aWZ5K2plZnNtaXRoQGdtYWlsLmNvbSIsImV4cCI6MTY4NDQxMjA5OH0.3UhLpWF_CQcYGd3ojC0KjVUVYCXODuz_TMAUuVLQB5E'

# fetch playlists again
from collections import OrderedDict

def fetch_playlists(is_public):
    playlists=OrderedDict()
    page_index=0
    page_limit=20
    while True:
        resp=apis.spotify.show_playlist_library(access_token=access_token, query='', is_public=is_public, page_index=page_index, page_limit=page_limit, sort_by=None)
        if not resp:
            break
        for pl in resp:
            playlists[pl['playlist_id']]={'playlist_id':pl['playlist_id'],'title':pl['title'],'is_public':pl['is_public'],'song_ids':list(pl.get('song_ids',[]))}
        page_index+=1
    return playlists

pl_public=fetch_playlists(True)
pl_private=fetch_playlists(False)
all_playlists={**pl_public, **{pid:pl for pid,pl in pl_private.items() if pid not in pl_public}}

# find any remaining playlist songs released after 2021
remaining_after_2021={}
for pid,pl in all_playlists.items():
    for sid in pl['song_ids']:
        sd=apis.spotify.show_song(song_id=sid)
        rd=sd.get('release_date')
        if rd and datetime.fromisoformat(rd).year>2021:
